import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static int K;
    static int MAXK;
    static int MAXD;
    static class State {
        int[][] mat;
        int[] inside;
        boolean[] exist;

        State() {
            mat = new int[MAXK][MAXK];
            inside = new int[MAXK];
            exist = new boolean[MAXK];
        }

        State(State other, int rot) {
            this();
            for (int i = 0; i < K; i++) {
                exist[(i + rot) % K] = other.exist[i];
                inside[(i + rot) % K] = other.inside[i];
                for (int j = 0; j < K; j++) {
                    mat[(i + rot) % K][(j + rot) % K] = other.mat[i][j];
                }
            }
        }

        State(State a, State b) {
            this();
            for (int i = 0; i < K; i++) {
                exist[i] = a.exist[i] || b.exist[i];
                inside[i] = a.inside[i];
                if (!a.exist[i]) inside[i] = (int)((inside[i] + (long)a.inside[i]) % MOD);
                for (int j = 0; j < K; j++) {
                    inside[i] = (int)((inside[i] + (long)a.mat[i][j] * b.inside[j]) % MOD);
                    mat[i][j] = 0;
                    if (!b.exist[j]) mat[i][j] = a.mat[i][j];
                    if (!a.exist[i]) mat[i][j] = (int)((mat[i][j] + (long)b.mat[i][j]) % MOD);
                    for (int m = 0; m < K; m++) {
                        mat[i][j] = (int)((mat[i][j] + (long)a.mat[i][m] * b.mat[m][j]) % MOD);
                    }
                }
            }
        }
    }

    static State[] pk;
    static int[] digits;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        K = sc.nextInt();

        // Set maximum sizes based on problem constraints
        MAXD = 64; // assuming maximum number of digits
        MAXK = 50; // assuming maximum K value

        pk = new State[MAXD];
        for (int i = 0; i < MAXD; i++) {
            pk[i] = new State();
        }
        digits = new int[MAXD];

        int len = 0;
        long x = n;
        while (x > 0) {
            digits[len++] = (int)(x % K);
            x /= K;
        }

        // Initialize pk[0]
        pk[0].exist[0] = true;
        pk[0].inside[0] = 1;
        for (int j = 0; j < K; j++) {
            pk[0].mat[0][j] = 1;
        }

        // Build pk array
        for (int i = 1; i < len; i++) {
            pk[i] = pk[i - 1];
            for (int v = 1; v < K; v++) {
                pk[i] = new State(pk[i], new State(pk[i - 1], v));
            }
        }

        State result = new State();
        int sum = 0;
        for (int i = len - 1; i >= 0; i--) {
            for (int v = 0; v < digits[i]; v++) {
                result = new State(result, new State(pk[i], (sum + v) % K));
            }
            sum += digits[i];
        }

        long total = 1;
        for (int i = 0; i < K; i++) {
            total = (total + result.inside[i]) % MOD;
        }

        System.out.println(total);
        sc.close();
    }
}
